```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment>
  a owl:Ontology ;
  rdfs:comment "Ontology of educational assessment modeled from corpus passages. Where passages disagree on classification (e.g. diagnostic as coordinate vs. subordinate to formative assessment, or reliability 'types' enumerated two different ways), both claims are encoded as axioms and the resulting tension is documented in rdfs:comment, per modeling instructions." .

#################################################################
## CORE CLASSES
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation", "evaluation" ;
  rdfs:comment "Systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "examination", "exam" ;
  rdfs:comment "Assessment is often used interchangeably with test but is not limited to tests; a test is a kind of assessment, typically a set of questions/tasks administered to measure knowledge, skill, aptitude, or ability." .

ea:AssessmentPhenomenon a owl:Class ;
  rdfs:comment "Umbrella class for assessment-related phenomena, practices and side-effects discussed in the corpus that are not themselves kinds of assessment (e.g. score inflation, measurement error)." .

#################################################################
## AXIS 1: PURPOSE (placement / formative / summative / diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  skos:altLabel "formative evaluation", "formative feedback", "assessment for learning", "educative assessment", "classroom assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists placement/formative/summative/diagnostic as four coordinate, pairwise-disjoint purpose categories (see PurposeCategory disjoint union), while another passage states 'A common form of formative assessment is diagnostic assessment', subordinating DiagnosticAssessment under FormativeAssessment. Both claims are asserted; because hasPurpose is functional and FormativePurpose/DiagnosticPurpose are disjoint, this combination is deliberately left unresolved (tension preserved rather than omitted)." .

#################################################################
## ASSESSOR AXIS (for formative / self-assessment)
#################################################################

ea:hasAssessor a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:AssessorCategory .

ea:AssessorCategory a owl:Class .
ea:TeacherAssessor a owl:Class ; rdfs:subClassOf ea:AssessorCategory .
ea:PeerAssessor a owl:Class ; rdfs:subClassOf ea:AssessorCategory .
ea:LearnerAssessor a owl:Class ; rdfs:subClassOf ea:AssessorCategory .
ea:AssessorCategory owl:disjointUnionOf ( ea:TeacherAssessor ea:PeerAssessor ea:LearnerAssessor ) .

ea:SelfAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:DiagnosticAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasAssessor ; owl:someValuesFrom ea:LearnerAssessor ] ) ] ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
## PERFORMANCE-BASED / AUTHENTIC ASSESSMENT
#################################################################

ea:hasOutputFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ;
  rdfs:range ea:OutputFormatCategory .

ea:OutputFormatCategory a owl:Class .
ea:ProductOutput a owl:Class ; rdfs:subClassOf ea:OutputFormatCategory .
ea:PerformanceOutput a owl:Class ; rdfs:subClassOf ea:OutputFormatCategory .
ea:OutputFormatCategory owl:disjointUnionOf ( ea:ProductOutput ea:PerformanceOutput ) .

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "performance test", "practical test" ;
  rdfs:comment "Similar to summative assessment, focuses on achievement via a well-defined task requiring an extended response; performance formats are classified into products and performances. Also described elsewhere as requiring the examinee to actually perform a task or activity (e.g. a behind-the-wheel driving test)." .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "TENSION: listed as a coordinate sibling of PerformanceBasedAssessment in the enumerated 'assessment types' list, yet another passage states 'performance assessments may also be called authentic assessments', i.e. treats them as synonymous. Both the coordinate listing and the synonym claim are preserved without forcing equivalence or disjointness." .

#################################################################
## AXIS 2: OBJECTIVITY (objective / subjective)
#################################################################

ea:hasObjectivity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ObjectivityCategory .

ea:ObjectivityCategory a owl:Class .
ea:ObjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

#################################################################
## AXIS 3: REFERENCING (criterion / norm / ipsative)
#################################################################

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ReferencingCategory ;
  rdfs:comment "Functional per primary use; corpus notes each referencing method 'can be used to grade the same test paper', i.e. the same artifact could in principle be scored under a different referencing scheme on a separate occasion." .

ea:ReferencingCategory a owl:Class .
ea:CriterionReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf ( ea:CriterionReferencedCategory ea:NormReferencedCategory ea:IpsativeCategory ) .

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencedCategory ] ) ] .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] .

ea:IpsativeAssessment a owl:Class ;
  skos:altLabel "forced-choice assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeCategory ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT", "standards-based assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencedCategory ] ) ] .

ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] .

ea:hasCutScore a owl:DatatypeProperty ;
  rdfs:domain ea:CriterionReferencedTest ;
  rdfs:range xsd:decimal ;
  rdfs:comment "Many, though not all, criterion-referenced tests involve a cutscore; the criterion itself is the domain of subject matter assessed, not the cutscore." .

#################################################################
## AXIS 4: FORMALITY (formal / informal)
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] .

#################################################################
## AXIS 5: LOCUS (internal / external)
#################################################################

ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:LocusCategory .

ea:LocusCategory a owl:Class .
ea:InternalCategory a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:ExternalCategory a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:LocusCategory owl:disjointUnionOf ( ea:InternalCategory ea:ExternalCategory ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalCategory ] ) ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalCategory ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
## AXIS 6: STANDARDIZATION
#################################################################

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:comment "Administered and scored in a consistent/standard manner for all test takers. Most standardized tests are summative assessments (stated as a tendency, not a strict subclass axiom)." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] .

#################################################################
## AXIS 7: STAKES
#################################################################

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with important consequences/a desired reward for good performance." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

ea:CompetitiveExamination a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ]
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected." .

#################################################################
## AXIS 8: GRANULARITY
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityCategory .

ea:GranularityCategory a owl:Class .
ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:ProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:GranularityCategory owl:disjointUnionOf ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

#################################################################
## AXIS 9: ADMINISTRATION MODE
#################################################################

ea:hasAdministrationMode a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:AdministrationModeCategory .

ea:AdministrationModeCategory a owl:Class .
ea:OralMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:PaperMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:ComputerMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory ; skos:altLabel "on-screen mode" .
ea:PracticalMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:AdministrationModeCategory owl:disjointUnionOf ( ea:OralMode ea:PaperMode ea:ComputerMode ea:PracticalMode ) .

ea:WrittenMode a owl:Class ;
  rdfs:comment "Grouping class for paper and computer modes; a written test is administered on paper or on a computer." .
ea:PaperMode rdfs:subClassOf ea:WrittenMode .
ea:ComputerMode rdfs:subClassOf ea:WrittenMode .

ea:WrittenTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:WrittenMode ] ) ] .

ea:OralTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:OralMode ] ) ] .

ea:ComputerBasedAssessment a owl:Class ;
  skos:altLabel "online assessment", "computerized assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:ComputerMode ] ) ] .

#################################################################
## TEST ITEMS
#################################################################

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:TestItem .

ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:Test .

ea:hasStem a owl:DatatypeProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range xsd:string .

ea:AnswerOption a owl:Class .

ea:hasKey a owl:ObjectProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:AnswerOption .

ea:hasDistractor a owl:ObjectProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:AnswerOption .

ea:TestItem a owl:Class ;
  rdfs:comment "The more general term for what is colloquially called a 'question'; items are stored in an item bank." .

ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:TestItem owl:disjointUnionOf ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:MultipleChoiceItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  skos:altLabel "MCQ" ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:AnswerOption ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ;
  rdfs:comment "Consists of a stem and alternative answers; only one answer may be keyed as correct." .

ea:TrueFalseItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "TENSION: one passage lists true/false as a coordinate objective item type alongside multiple-choice; another passage describes true/false as one of 'two families of multiple-choice questions', i.e. a subtype of MultipleChoiceItem. Both the sibling (ObjectiveItem) and subordinate (MultipleChoiceItem) placements are asserted, even though MultipleChoiceItem requires exactly one key while true/false 'requires choosing all answers that are appropriate', an unresolved conflict." .

ea:MultipleResponseItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "More than one answer may be keyed as correct, contrasting with multiple-choice items." .

ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

ea:FillInTheBlankItem a owl:Class ;
  rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Provides identifying characteristics and requires the test taker to recall the correct term; may or may not supply a word bank." .

ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:TestItem .

ea:EssayItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "essay question" .

ea:FreeResponseItem a owl:Class ;
  skos:altLabel "FRQ", "free response question" ;
  owl:equivalentClass ea:EssayItem ;
  rdfs:comment "Per the corpus, 'a free response question (FRQ) or essay question is a type of open-ended question', treated as the same kind; EssayItem and FreeResponseItem are modeled as equivalent." .

ea:ExtendedResponseItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveItem ;
  rdfs:comment "TENSION: another passage states 'Subjective questions include extended-response and essay questions' as two coordinate types, conflicting with the FRQ/essay equivalence noted on EssayItem." .

ea:MultipleChoiceTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasItem ; owl:someValuesFrom ea:MultipleChoiceItem ] ) ] .

#################################################################
## RUBRICS AND GRADING
#################################################################

ea:Criterion a owl:Class .

ea:hasCriterion a owl:ObjectProperty ;
  rdfs:domain ea:Rubric ;
  rdfs:range ea:Criterion .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Rubric .

ea:Rubric a owl:Class ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses; contains evaluative criteria, quality definitions, and a scoring strategy." .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Evaluates various dimensions or components separately." .
ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ) .

ea:DevelopmentalRubric a owl:Class ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "A subset of analytical rubrics; facilitates assessment, instructional design, and transformative learning through multiple dimensions of developmental successions." .

ea:GradingApproach a owl:Class .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ; skos:altLabel "holistic scoring", "nonreductionist grading" .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach .
ea:GradingApproach owl:disjointUnionOf ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ;
  rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "Trains raters to score against a scoring guide with multiple criteria; 'comes close to' analytic scoring methods but 'remains holistic at heart', a hybrid not cleanly placed in the holistic/analytic partition." .

ea:hasScoringApproach a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GradingApproach .

#################################################################
## VALIDITY
#################################################################

ea:hasValidity a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Validity .

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which an assessment measures what it is intended to measure." .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: one passage lists content, criterion, construct, consequential and face validity as coordinate categories of validity evidence (asserted pairwise disjoint above); another passage states construct validity 'subsumes all other types of validity' and that modern validity theory treats it as 'the overarching concern...subsuming all other types of validity evidence such as content validity and criterion validity' (asserted here as subClassOf). Both claims are preserved, producing an unresolved tension (disjoint siblings that are also subsumed)." .

ea:hasTiming a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionValidity ;
  rdfs:range ea:TimingCategory .

ea:TimingCategory a owl:Class .
ea:ConcurrentTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:PredictiveTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:TimingCategory owl:disjointUnionOf ( ea:ConcurrentTiming ea:PredictiveTiming ) .

ea:ConcurrentValidity a owl:Class ;
  rdfs:subClassOf ea:CriterionValidity ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasTiming ; owl:someValuesFrom ea:ConcurrentTiming ] ) ] ;
  rdfs:comment "Test data and criterion data are collected at the same time." .

ea:PredictiveValidity a owl:Class ;
  rdfs:subClassOf ea:CriterionValidity ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasTiming ; owl:someValuesFrom ea:PredictiveTiming ] ) ] ;
  rdfs:comment "Test data are collected first in order to predict criterion data collected at a later time." .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
